1: import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
2: import {
3:   ArrowsClockwiseIcon,
4:   FolderOpenIcon,
5:   ImageIcon,
6:   ListBulletsIcon,
7:   MagnifyingGlassIcon,
8:   SquaresFourIcon,
9: } from '@phosphor-icons/react';
10: import { deleteMaterial, fetchMaterials, fetchMaterialSummary } from '../../services/materialApi';
11: import type { ChatMaterialItem, ChatMaterialSummary } from '../../types/material';
12: import { Button } from '../common/Button';
13: import { ConfirmDialog } from '../common/ConfirmDialog';
14: import { useMessage } from '../common/Message';
15: import { Select } from '../common/Select';
16: import { Skeleton } from '../common/Skeleton';
17: import { TopBar } from '../common/TopBar';
18: import { TopBarAction } from '../common/TopBarAction';
19: import { MaterialCollectionView } from './MaterialCollectionView';
20: import { MaterialPreviewModal } from './MaterialPreviewModal';
21: import { formatMaterialBytes } from './materialsPresentation';
22: import styles from './MaterialsPage.module.css';
23: 
24: interface MaterialsPageProps {
25:   existingSessionIds: Set<string>;
26:   onOpenSession: (sessionId: string) => void;
27: }
28: 
29: const PAGE_SIZE = 40;
30: 
31: export function MaterialsPage({ existingSessionIds, onOpenSession }: MaterialsPageProps) {
32:   const { showMessage } = useMessage();
33:   const [items, setItems] = useState<ChatMaterialItem[]>([]);
34:   const [total, setTotal] = useState(0);
35:   const [summary, setSummary] = useState<ChatMaterialSummary | null>(null);
36:   const [loading, setLoading] = useState(true);
37:   const [loadingMore, setLoadingMore] = useState(false);
38:   const [error, setError] = useState<string | null>(null);
39: 
40:   const [query, setQuery] = useState('');
41:   const [channel, setChannel] = useState('');
42:   const [sessionKind, setSessionKind] = useState('');
43:   const [subType, setSubType] = useState('');
44:   const [sessionId, setSessionId] = useState('');
45:   const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
46: 
47:   const [previewItem, setPreviewItem] = useState<ChatMaterialItem | null>(null);
48:   const [deleteTarget, setDeleteTarget] = useState<ChatMaterialItem | null>(null);
49:   const [deleting, setDeleting] = useState(false);
50:   const requestSeq = useRef(0);
51: 
52:   const load = useCallback(async () => {
53:     const seq = ++requestSeq.current;
54:     setLoading(true);
55:     setError(null);
56:     try {
57:       const [page, sum] = await Promise.all([
58:         fetchMaterials({
59:           channel: channel || undefined,
60:           sessionKind: sessionKind || undefined,
61:           subType: subType || undefined,
62:           sessionId: sessionId || undefined,
63:           query: query.trim() || undefined,
64:           limit: PAGE_SIZE,
65:           offset: 0,
66:         }),
67:         fetchMaterialSummary(),
68:       ]);
69:       if (seq !== requestSeq.current) return;
70:       setItems(page.items);
71:       setTotal(page.total);
72:       setSummary(sum);
73:     } catch (reason) {
74:       if (seq === requestSeq.current) {
75:         setError(reason instanceof Error ? reason.message : '档案加载失败');
76:       }
77:     } finally {
78:       if (seq === requestSeq.current) setLoading(false);
79:     }
80:   }, [channel, query, sessionId, sessionKind, subType]);
81: 
82:   useEffect(() => {
83:     const timer = window.setTimeout(() => void load(), query ? 220 : 0);
84:     return () => {
85:       window.clearTimeout(timer);
86:       requestSeq.current += 1;
87:     };
88:   }, [load, query]);
89: 
90:   const loadMore = async () => {
91:     if (loadingMore || items.length >= total) return;
92:     setLoadingMore(true);
93:     try {
94:       const page = await fetchMaterials({
95:         channel: channel || undefined,
96:         sessionKind: sessionKind || undefined,
97:         subType: subType || undefined,
98:         sessionId: sessionId || undefined,
99:         query: query.trim() || undefined,
100:         limit: PAGE_SIZE,
101:         offset: items.length,
102:       });
103:       setItems((prev) => [...prev, ...page.items]);
104:       setTotal(page.total);
105:     } catch (reason) {
106:       showMessage('error', reason instanceof Error ? reason.message : '加载更多失败');
107:     } finally {
108:       setLoadingMore(false);
109:     }
110:   };
111: 
112:   const handleConfirmDelete = async () => {
113:     if (!deleteTarget) return;
114:     setDeleting(true);
115:     try {
116:       await deleteMaterial(deleteTarget.fileId);
117:       if (previewItem?.fileId === deleteTarget.fileId) setPreviewItem(null);
118:       setDeleteTarget(null);
119:       showMessage('success', '档案素材已删除');
120:       await load();
121:     } catch (reason) {
122:       showMessage('error', reason instanceof Error ? reason.message : '删除失败');
123:     } finally {
124:       setDeleting(false);
125:     }
126:   };
127: 
128:   const hasFilters = Boolean(channel || sessionKind || subType || sessionId || query.trim());
129:   const sessionOptions = useMemo(() => [
130:     { value: '', label: '全部对话' },
131:     ...(summary?.sessions ?? []).map((bucket) => ({
132:       value: bucket.sessionId,
133:       label: `${bucket.sessionTitle || '新对话'} (${bucket.count})`,
134:     })),
135:   ], [summary]);
136: 
137:   const clearFilters = () => {
138:     setQuery('');
139:     setChannel('');
140:     setSessionKind('');
141:     setSubType('');
142:     setSessionId('');
143:   };
144: 
145:   return (
146:     <main className={styles.workspace}>
147:       <TopBar
148:         title="档案"
149:         subtitle="对话素材归档"
150:         icon={<FolderOpenIcon size={16} />}
151:         search={
152:           <div className={styles.search}>
153:             <MagnifyingGlassIcon size={15} />
154:             <input
155:               value={query}
156:               onChange={(event) => setQuery(event.target.value)}
157:               aria-label="搜索档案"
158:               placeholder="搜索文件名、对话标题、ID 或归档路径…"
159:             />
160:           </div>
161:         }
162:         actions={
163:           <>
164:             <TopBarAction
165:               iconOnly
166:               aria-label={viewMode === 'grid' ? '切换列表视图' : '切换网格视图'}
167:               title={viewMode === 'grid' ? '切换列表视图' : '切换网格视图'}
168:               onClick={() => setViewMode((prev) => (prev === 'grid' ? 'list' : 'grid'))}
169:             >
170:               {viewMode === 'grid' ? <ListBulletsIcon size={15} /> : <SquaresFourIcon size={15} />}
171:             </TopBarAction>
172:             <TopBarAction
173:               iconOnly
174:               aria-label="刷新档案"
175:               title="刷新档案"
176:               onClick={() => void load()}
177:             >
178:               <ArrowsClockwiseIcon size={15} />
179:             </TopBarAction>
180:           </>
181:         }
182:       />
183: 
184:       <div className={styles.content}>
185:         <section className={styles.summaryBar} aria-label="档案存储概览" aria-busy={loading}>
186:           {loading && !summary ? (
187:             <div className={styles.summaryLoading}>
188:               <Skeleton variant="text" decorative />
189:               <Skeleton variant="text" decorative />
190:               <Skeleton variant="text" decorative />
191:             </div>
192:           ) : summary ? (
193:             <>
194:               <div className={styles.statCell}>
195:                 <strong>{summary.totalCount}</strong>
196:                 <span>已归档文件</span>
197:               </div>
198:               <div className={styles.statCell}>
199:                 <strong>{formatMaterialBytes(summary.totalBytes)}</strong>
200:                 <span>本地存储占用</span>
201:               </div>
202:               <div className={styles.statCell}>
203:                 <strong>{summary.byCategory.IMAGE ?? 0}</strong>
204:                 <span>图片资料</span>
205:               </div>
206:               <div className={styles.statCell}>
207:                 <strong>{summary.sessions.length}</strong>
208:                 <span>关联对话数</span>
209:               </div>
210:               <p className={styles.storageHint}>
211:                 按渠道 / 会话类型 / 会话 ID / 格式 / 日期自动分类归档于 <code>.butvan-agent/materials/</code>
212:               </p>
213:             </>
214:           ) : (
215:             <span className={styles.summaryUnavailable}>档案概览暂不可用</span>
216:           )}
217:         </section>
218: 
219:         <section className={styles.filterBar} aria-label="档案筛选">
220:           <div className={styles.filterGroup}>
221:             <Select
222:               aria-label="来源渠道"
223:               fieldSize="sm"
224:               value={channel}
225:               onChange={(event) => setChannel(event.target.value)}
226:               options={[
227:                 { value: '', label: '全部渠道' },
228:                 { value: 'DESKTOP', label: '桌面端' },
229:                 { value: 'FEISHU', label: '飞书' },
230:               ]}
231:             />
232:             <Select
233:               aria-label="会话类型"
234:               fieldSize="sm"
235:               value={sessionKind}
236:               onChange={(event) => setSessionKind(event.target.value)}
237:               options={[
238:                 { value: '', label: '全部类型' },
239:                 { value: 'GENERAL', label: '普通对话' },
240:                 { value: 'PROJECT', label: '项目对话' },
241:               ]}
242:             />
243:             <Select
244:               aria-label="文件格式"
245:               fieldSize="sm"
246:               value={subType}
247:               onChange={(event) => setSubType(event.target.value)}
248:               options={[
249:                 { value: '', label: '全部格式' },
250:                 { value: 'PNG', label: 'PNG' },
251:                 { value: 'JPEG', label: 'JPEG' },
252:                 { value: 'WEBP', label: 'WEBP' },
253:                 { value: 'GIF', label: 'GIF' },
254:               ]}
255:             />
256:             <Select
257:               aria-label="所属对话"
258:               fieldSize="sm"
259:               value={sessionId}
260:               onChange={(event) => setSessionId(event.target.value)}
261:               options={sessionOptions}
262:             />
263:           </div>
264:           <div className={styles.filterRight}>
265:             <span className={styles.countText}>共 {total} 项</span>
266:             {hasFilters && (
267:               <Button size="sm" variant="ghost" onClick={clearFilters}>
268:                 重置筛选
269:               </Button>
270:             )}
271:           </div>
272:         </section>
273: 
274:         {error && (
275:           <div className={styles.errorBanner} role="alert">
276:             <span>{error}</span>
277:             <Button size="sm" variant="outline" onClick={() => void load()}>
278:               重新加载
279:             </Button>
280:           </div>
281:         )}
282: 
283:         {loading && items.length === 0 ? (
284:           <div className={styles.skeletonWrap}>
285:             <Skeleton variant="document" label="正在整理对话档案…" />
286:           </div>
287:         ) : items.length === 0 ? (
288:           <div className={styles.emptyState}>
289:             <ImageIcon size={24} />
290:             <strong>{hasFilters ? '没有符合筛选条件的档案' : '暂无已保存的对话档案'}</strong>
291:             <span>
292:               {hasFilters
293:                 ? '尝试调整渠道、会话或格式筛选条件。'
294:                 : '在对话中向 Agent 发送图片后，系统会自动生成唯一 ID 并按分类目录保存于此。'}
295:             </span>
296:             {hasFilters && (
297:               <Button size="sm" variant="primary" onClick={clearFilters}>
298:                 查看全部档案
299:               </Button>
300:             )}
301:           </div>
302:         ) : (
303:           <MaterialCollectionView
304:             items={items}
305:             viewMode={viewMode}
306:             onPreview={setPreviewItem}
307:             onDelete={setDeleteTarget}
308:           />
309:         )}
310: 
311:         {items.length < total && (
312:           <div className={styles.loadMoreRow}>
313:             <Button variant="outline" size="sm" disabled={loadingMore} onClick={() => void loadMore()}>
314:               {loadingMore ? '加载中…' : `加载更多（已显示 ${items.length} / ${total}）`}
315:             </Button>
316:           </div>
317:         )}
318:       </div>
319: 
320:       <MaterialPreviewModal
321:         item={previewItem}
322:         canOpenSession={Boolean(previewItem && existingSessionIds.has(previewItem.sessionId))}
323:         onClose={() => setPreviewItem(null)}
324:         onOpenSession={onOpenSession}
325:         onRequestDelete={(item) => setDeleteTarget(item)}
326:       />
327: 
328:       <ConfirmDialog
329:         open={Boolean(deleteTarget)}
330:         title="确认删除档案素材"
331:         tone="danger"
332:         confirmText="永久删除"
333:         confirmVariant="danger"
334:         busy={deleting}
335:         description={`确定要永久删除“${deleteTarget?.originalName ?? ''}”吗？本地归档文件与数据库记录将一并清理，无法恢复。`}
336:         onClose={() => { if (!deleting) setDeleteTarget(null); }}
337:         onConfirm={() => void handleConfirmDelete()}
338:       />
339:     </main>
340:   );
341: }

