5:   if (bytes < 1024) return `${bytes} B`;
6:   if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
7:   return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
8: }
