                onClick={() => onDelete(item)}
              >
                <TrashIcon size={14} />
              </button>
            </div>
            <div className={styles.cardBadges}>
              <Badge variant="default">{item.subType}</Badge>
              <Badge variant={item.channel === 'FEISHU' ? 'purple' : 'primary'}>
                {channelLabel(item.channel)}
              </Badge>
              <Badge variant="default">{sessionKindLabel(item.sessionKind)}</Badge>
            </div>
            <div className={styles.cardMeta} title={item.sessionTitle}>
              <span>{item.sessionTitle}</span>
              <span>{formatMaterialBytes(item.sizeBytes)}</span>
            </div>
            <div className={styles.cardPath} title={`.butvan-agent/materials/${item.archivePath}`}>
              ID: {shortFileId(item.fileId)} · {item.createdDate}
            </div>
          </div>
        </article>
      ))}
    </div>
  );
}

args.Content:
.workspace {
  flex: 1;
  min-width: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
  background: var(--bg-app, #ffffff);
  overflow: hidden;
}

.search {
  width: 100%;
  height: 32px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  border-radius: var(--radius-lg, 8px);
  background: var(--bg-surface, #f8f9fa);
  color: var(--text-muted, #9ca3af);
  min-width: 200px;
  transition: background var(--transition-fast, 150ms ease);
}

.search:focus-within {
  background: var(--bg-app, #ffffff);
  outline: 1px solid var(--border-focus, #3b82f6);
}

.search input {
  width: 100%;
  border: none;
  background: transparent;
  outline: none;
  font-family: inherit;
  font-size: 12.5px;
  color: var(--text-primary, #111827);
  user-select: text;
}

.search input::placeholder {
  color: var(--text-muted, #9ca3af);
}

.content {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 18px 32px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border-subtle, #e5e7eb);
}

.filterGroup {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  margin-left: -6px;
}

.summaryInline {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  color: var(--text-muted, #9ca3af);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.summaryLoading {
  width: 150px;
}

.summaryMetric {
  color: var(--text-secondary, #4b5563);
}

.summaryDivider {
  color: var(--border-medium, #d1d5db);
}

.errorBanner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
  border-radius: var(--radius-lg, 8px);
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
  font-size: 13px;
}

.skeletonWrap {
  padding: 8px 0;
}

.emptyState {
  margin: 48px auto;
  max-width: 360px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 8px;
  color: var(--text-muted, #9ca3af);
  font-size: 13px;
}

.emptyState strong {
  color: var(--text-primary, #111827);
  font-size: 14px;
  font-weight: 500;
}

/* Date groups */
.groups {
  display: flex;
  flex-direction: column;
  gap: 30px;
}

.dateGroup {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.groupHeader {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.groupTitle {
  margin: 0;
  font-size: 13px;
  font-weight: 550;
  color: var(--text-secondary, #4b5563);
  letter-spacing: -0.01em;
}

.groupCount {
  font-size: 12px;
  color: var(--text-muted, #9ca3af);
  font-variant-numeric: tabular-nums;
}

/* Minimal gallery grid */
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(216px, 1fr));
  gap: 24px 18px;
}

.card {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.thumbFrame {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  border-radius: 10px;
  background: var(--bg-surface, #f8f9fa);
  border: 1px solid rgba(17, 24, 39, 0.07);
  overflow: hidden;
  transition: border-color var(--transition-fast, 150ms ease);
}

.card:hover .thumbFrame {
  border-color: rgba(17, 24, 39, 0.16);
}

.thumbBtn {
  width: 100%;
  height: 100%;
  border: none;
  padding: 0;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--text-muted, #9ca3af);
}

.thumbImg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 240ms cubic-bezier(0.22, 1, 0.36, 1);
}

.card:hover .thumbImg {
  transform: scale(1.025);
}

.cardDeleteBtn {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 26px;
  height: 26px;
  border: 1px solid rgba(17, 24, 39, 0.08);
  border-radius: var(--radius-full, 9999px);
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  color: var(--text-secondary, #4b5563);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  opacity: 0;
  transition: opacity var(--transition-fast, 150ms ease),
    color var(--transition-fast, 150ms ease),
    background var(--transition-fast, 150ms ease),
    border-color var(--transition-fast, 150ms ease);
}

.card:hover .cardDeleteBtn,
.card:focus-within .cardDeleteBtn {
  opacity: 1;
}

.cardDeleteBtn:hover {
  background: #ffffff;
  border-color: #fecaca;
  color: #dc2626;
}

.cardCaption {
  padding: 8px 2px 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.cardTitle {
  border: none;
  background: transparent;
  padding: 0;
  text-align: left;
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary, #111827);
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
  transition: color var(--transition-fast, 150ms ease);
}

.cardTitle:hover {
  color: var(--border-focus, #3b82f6);
}

.cardMeta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 12px;
  color: var(--text-muted, #9ca3af);
  min-width: 0;
}

.cardSession {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.cardSize {
  flex-shrink: 0;
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
}

/* Minimal divider list */
.list {
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--border-subtle, #e5e7eb);
}

.listRow {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 8px;
  border-bottom: 1px solid var(--border-subtle, #e5e7eb);
  border-radius: var(--radius-md, 6px);
  transition: background var(--transition-fast, 150ms ease);
}

.listRow:hover {
  background: var(--bg-surface, #f8f9fa);
}

.listThumb {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md, 6px);
  border: 1px solid rgba(17, 24, 39, 0.07);
  background: var(--bg-surface, #f8f9fa);
  padding: 0;
  overflow: hidden;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--text-muted, #9ca3af);
}

.listThumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.listMain {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.listTitle {
  border: none;
  background: transparent;
  padding: 0;
  text-align: left;
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary, #111827);
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
  align-self: flex-start;
  transition: color var(--transition-fast, 150ms ease);
}

.listTitle:hover {
  color: var(--border-focus, #3b82f6);
}

.listSub {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-muted, #9ca3af);
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
}

.listSession {
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 240px;
}

.dot {
  color: var(--border-medium, #d1d5db);
  flex-shrink: 0;
}

.listRight {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
  font-size: 12px;
  color: var(--text-muted, #9ca3af);
  font-variant-numeric: tabular-nums;
}

.listFormat {
  font-size: 11px;
  letter-spacing: 0.02em;
  color: var(--text-muted, #9ca3af);
}

.listSize {
  min-width: 60px;
  text-align: right;
  color: var(--text-secondary, #4b5563);
}

.listDeleteBtn {
  border: none;
  background: transparent;
  color: var(--text-muted, #9ca3af);
  padding: 5px;
  border-radius: var(--radius-md, 6px);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity var(--transition-fast, 150ms ease),
    background var(--transition-fast, 150ms ease),
    color var(--transition-fast, 150ms ease);
}

.listRow:hover .listDeleteBtn,
.listRow:focus-within .listDeleteBtn {
  opacity: 1;
}

.listDeleteBtn:hover {
  background: #fee2e2;
  color: #dc2626;
}

.loadMoreRow {
  display: flex;
  justify-content: center;
  padding-top: 8px;
}

@media (max-width: 720px) {
  .content {
    padding: 14px 16px 32px;
    gap: 18px;
  }

  .grid {
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 18px 12px;
  }

  .cardDeleteBtn,
  .listDeleteBtn {
    opacity: 1;
  }

  .listFormat {
    display: none;
  }
}

